// 1. Lấy đoạn text chứa JSON từ kết quả của Gemini
let rawText = $input.first().json.content.parts[0].text;

// 2. Dọn dẹp phòng trường hợp AI "vui tính" chèn thêm markdown (```json ... ```)
let cleanText = rawText.replace(/```json/g, "").replace(/```/g, "").trim();

// 3. Chuyển chữ thành mảng dữ liệu (Array of Objects)
let records = JSON.parse(cleanText);

// 4. Trả về định dạng n8n yêu cầu (Mỗi công nhân là 1 item riêng biệt)
return records.map(item => ({ json: item }));

